from collections import Counter
import csv
import hashlib
import json
from pathlib import Path
import statistics

HERE = Path(__file__).resolve().parent
RUN = HERE / 'optimization-comparison'
METRICS = ['connectionNs', 'prepareNs', 'evaluateNs', 'firstRowAfterEvaluateNs', 'consumeNs',
           'closeNs', 'retainedReadNs', 'totalNs', 'allThreadAllocatedBytes', 'callerThreadAllocatedBytes',
           'ledgerPeakBytes', 'lazyValueCalls']
PAIRS = [('original-dense','original-off'), ('candidate1-dense','original-dense'),
         ('candidate1-and-2-dense','candidate1-dense'), ('candidate1-dense','original-off'),
         ('candidate1-and-2-dense','original-off'), ('candidate1-and-2-dense','original-dense')]


def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def write(path, value):
    with path.open('x') as stream:
        json.dump(value,stream,indent=2,sort_keys=True)
        stream.write('\n')


def csv_write(path, records):
    with path.open('x',newline='') as stream:
        writer = csv.DictWriter(stream,fieldnames=list(records[0]))
        writer.writeheader()
        writer.writerows(records)


def route(sample):
    counters=sample['counters']
    return {'selections':sample['successfulSelections'],
            'compiledBinds':counters['compiledBinds'],'interpretedBinds':counters['interpretedBinds'],
            'aggregateCompiledBinds':counters['aggregateCompiledBinds'],
            'aggregateInterpretedBinds':counters['aggregateInterpretedBinds'],
            'semanticNativeCompiles':counters['semanticNativeCompiles']}


def histogram(samples):
    counts=Counter(json.dumps(route(s),sort_keys=True) for s in samples)
    return [{'signature':json.loads(k),'count':v} for k,v in sorted(counts.items())]


